    ("grupo(c, 'Fatiga', ", "grupo(c, 'Fatigue', "),
    ("grupo(c, 'Siempre', [op('Coordination', '−1', S.coord, set('coord', !S.coord)), op('Formaciones mezcladas', '−1', S.mixta, set('mixta', !S.mixta)), op('Prepared Defense', 'máx. Partial', S.pd, set('pd', !S.pd))]);",
     "grupo(c, 'Always', [op('Coordination', '−1', S.coord, set('coord', !S.coord)), op('Mixed formations', '−1', S.mixta, set('mixta', !S.mixta)), op('Prepared Defense', 'max. Partial', S.pd, set('pd', !S.pd))]);"),
    ("grupo(c, 'La MSR', [op('Completa', '', S.msr === 'completa', set('msr', 'completa')), op('No completa', '', S.msr === 'rota', set('msr', 'rota'))]);",
     "grupo(c, 'The MSR', [op('Complete', '', S.msr === 'completa', set('msr', 'completa')), op('Not complete', '', S.msr === 'rota', set('msr', 'rota'))]);"),
    ("grupo(c, 'Con la MSR completa', [op('Trenes a 5-15 hexes del HQ', '+1', S.optima, set('optima', !S.optima)), op('Trenes Ghost', '−1', S.ghost, set('ghost', !S.ghost)),",
     "grupo(c, 'With a Complete MSR', [op('Trains 5-15 hexes from the HQ', '+1', S.optima, set('optima', !S.optima)), op('Ghost trains', '−1', S.ghost, set('ghost', !S.ghost)),"),
    ("grupo(c, 'Pistas (Tracks) en la MSR', [op('No', '', S.pistas === 'no', set('pistas', 'no')), op('Con buen tiempo', '−1', S.pistas === 'buena', set('pistas', 'buena')), op('Con mal tiempo', '−2', S.pistas === 'mala', set('pistas', 'mala'))]);",
     "grupo(c, 'Tracks on the MSR', [op('No', '', S.pistas === 'no', set('pistas', 'no')), op('In good weather', '−1', S.pistas === 'buena', set('pistas', 'buena')), op('In bad weather', '−2', S.pistas === 'mala', set('pistas', 'mala'))]);"),
    ("grupo(c, 'Con la MSR rota (trenes fuera: −3)', [op('Sin marcador', '', S.bloqueo === 0, set('bloqueo', 0)),", "grupo(c, 'With a broken MSR (trains off-map: −3)', [op('No marker', '', S.bloqueo === 0, set('bloqueo', 0)),"),
    ("grupo(c, 'Modificador del juego', ", "grupo(c, 'Game modifier', "),
